def make_loss_single_head(cfg, num_classes):
    """Like make_loss but applies triplet only to feat[0] (primary head)."""
    loss_func_base, center_criterion = make_loss(cfg, num_classes)
    triplet = TripletLoss() if cfg.MODEL.NO_MARGIN else TripletLoss(cfg.SOLVER.MARGIN)

    def loss_func(score, feat, target, target_cam=None, i2tscore=None, isprint=False):
        if cfg.MODEL.IF_LABELSMOOTH == 'on':
            xent = CrossEntropyLabelSmooth(num_classes=num_classes)
            ce_fn = xent
        else:
            ce_fn = F.cross_entropy

        if isinstance(score, list):
            ID_LOSS = sum(ce_fn(s, target) for s in score)
        else:
            ID_LOSS = ce_fn(score, target)

        primary_feat = feat[0] if isinstance(feat, list) else feat
        TRI_LOSS = triplet(primary_feat, target)[0]

        loss = cfg.MODEL.ID_LOSS_WEIGHT * ID_LOSS + cfg.MODEL.TRIPLET_LOSS_WEIGHT * TRI_LOSS

        if i2tscore is not None:
            if isinstance(i2tscore, list):
                I2T_LOSS = sum(ce_fn(s, target) for s in i2tscore)
            else:
                I2T_LOSS = ce_fn(i2tscore, target)
            loss = cfg.MODEL.I2T_LOSS_WEIGHT * I2T_LOSS + loss

        return loss

    return loss_func, center_criterion


def make_loss_q_triplet(cfg, num_classes, feat_dim=None, n_qubits=6, n_layers=1):
    """
    Like make_loss but replaces TripletLoss with QuantumTripletLoss.

    Returns (loss_func, center_criterion, q_triplet).
    Attach q_triplet to model before building optimizer so its params are included:
        model.q_triplet = q_triplet
    """
    loss_func_base, center_criterion = make_loss(cfg, num_classes)

    q_triplet = QuantumTripletLoss(feat_dim=feat_dim, n_qubits=n_qubits, n_layers=n_layers)

    def loss_func(score, feat, target, target_cam=None, i2tscore=None, isprint=False):
        import torch.nn.functional as F

        if isinstance(score, list):
            ID_LOSS = sum(F.cross_entropy(s, target) for s in score)
        else:
            ID_LOSS = F.cross_entropy(score, target)

        if isinstance(feat, list):
            TRI_LOSS = sum(q_triplet(f, target)[0] for f in feat)
        else:
            TRI_LOSS = q_triplet(feat, target)[0]

        loss = cfg.MODEL.ID_LOSS_WEIGHT * ID_LOSS + cfg.MODEL.TRIPLET_LOSS_WEIGHT * TRI_LOSS

        if i2tscore is not None:
            if isinstance(i2tscore, list):
                I2T_LOSS = sum(F.cross_entropy(s, target) for s in i2tscore)
            else:
                I2T_LOSS = F.cross_entropy(i2tscore, target)
            loss = cfg.MODEL.I2T_LOSS_WEIGHT * I2T_LOSS + loss

        return loss

    return loss_func, center_criterion, q_triplet


def make_loss_qplr(cfg, num_classes,
                   top_k: int = 32,
                   n_qubits: int = 8,
                   n_layers: int = 2,
                   kl_weight: float = 0.5):
    """
    Like make_loss but adds a QuantumLabelRefiner that computes a KL loss
    on the classifier's output logits, capturing inter-class quantum correlations.

    Returns:
        loss_func_qplr  — same signature as make_loss; adds KL term
        center_criterion
        q_refiner       — QuantumLabelRefiner instance (attach to model:
                          model.q_refiner = q_refiner)
    """
    loss_func, center_criterion = make_loss(cfg, num_classes)

    q_refiner = QuantumLabelRefiner(
        num_classes=num_classes,
        top_k=top_k,
        n_qubits=n_qubits,
        n_layers=n_layers,
        kl_weight=kl_weight,
    )

    def loss_func_qplr(score, feat, target, target_cam=None, i2tscore=None, isprint=False):
        # Standard loss
        base_loss = loss_func(score, feat, target, target_cam, i2tscore, isprint)

        # QPLR KL loss on primary classifier head
        primary_score = score[0] if isinstance(score, list) else score
        kl_loss = q_refiner(primary_score, target)

        return base_loss + kl_loss

    return loss_func_qplr, center_criterion, q_refiner

